function progressOf(tasks){if(!tasks.length||tasks.some(t=>!hasProgress(t)))return null;if(tasks.every(t=>t.progress===100))return 100;if(tasks.some(t=>!hasPlan(t)))return null;const days=tasks.reduce((n,t)=>n+duration(t),0);return days?Math.min(99,Math.round(tasks.reduce((n,t)=>n+duration(t)*t.progress,0)/days)):null}
