function orderPeers(kind,record){return kind==='group'?state.groups:state.tasks.filter(t=>t.groupId===record.groupId&&(t.parentId||null)===(record.parentId||null))}

let orderSelection=null,orderTarget=null;
function orderRecord(kind,id){return (kind==='group'?state.groups:kind==='task'?state.tasks:[]).find(t=>t.id===id)}
function orderLabel(kind,record){return (kind==='group'?String(state.groups.findIndex(g=>g.id===record.id)+1):taskPaths().get(record.id)||'')+' · '+record.name}
function orderCompatible(kind,source,target){return Boolean(source&&target&&source.id!==target.id&&(kind==='group'||(source.groupId===target.groupId&&(source.parentId||null)===(target.parentId||null))))}
function wbsMarkup(kind,record,code){return '<span class="wbs-code wbs-reorder" data-reorder-kind="'+kind+'" data-reorder-id="'+escapeHTML(record.id)+'" role="button" tabindex="'+(isEditor?'0':'-1')+'" aria-disabled="'+(!isEditor)+'" aria-pressed="false" title="'+escapeHTML(code)+' · คลิกเพื่อเลือกย้ายลำดับ" aria-label="เลือกย้ายลำดับ '+escapeHTML(code+' '+record.name)+'">'+escapeHTML(code)+'</span>'}
function refreshOrderUI(){
 if(!isEditor||!orderRecord(orderSelection?.kind,orderSelection?.id)){orderSelection=null;orderTarget=null}
 const source=orderSelection?orderRecord(orderSelection.kind,orderSelection.id):null;
 document.querySelectorAll('[data-reorder-id]').forEach(el=>{const selected=Boolean(source&&el.dataset.reorderKind===orderSelection.kind&&el.dataset.reorderId===source.id),peer=Boolean(source&&el.dataset.reorderKind===orderSelection.kind&&orderCompatible(orderSelection.kind,source,orderRecord(el.dataset.reorderKind,el.dataset.reorderId)));el.setAttribute('tabindex',isEditor?'0':'-1');el.setAttribute('aria-disabled',String(!isEditor));el.setAttribute('aria-pressed',String(selected));el.classList.toggle('is-order-picked',selected);el.classList.toggle('is-order-peer',peer)});
 $('reorder-hint').hidden=!source;if(source)$('reorder-message').textContent='กำลังย้าย '+orderLabel(orderSelection.kind,source)+' · คลิกเลข WBS ปลายทางใต้หัวข้อแม่เดียวกัน แล้วเลือกวางก่อนหรือหลัง';
}
function cancelOrderMove(){const active=Boolean(orderSelection);orderSelection=null;orderTarget=null;if($('order-dialog').open)$('order-dialog').close();if(active)render()}
function pickOrderNode(kind,id){
 if(!requireEditor())return false;const record=orderRecord(kind,id);if(!record)return false;
 if(!orderSelection){if(orderPeers(kind,record).length<2){toast('รายการนี้ไม่มีรายการอื่นภายใต้หัวข้อเดียวกันให้ย้ายลำดับ');return false}orderSelection={kind,id};refreshOrderUI();return true}
 if(orderSelection.kind===kind&&orderSelection.id===id){cancelOrderMove();return true}
 const source=orderRecord(orderSelection.kind,orderSelection.id);if(kind!==orderSelection.kind||!orderCompatible(kind,source,record)){toast('กรุณาคลิกปลายทางที่อยู่ภายใต้หัวข้อแม่เดียวกัน');return false}
 orderTarget={kind,id};$('order-source-label').textContent=orderLabel(kind,source);$('order-target-label').textContent=orderLabel(kind,record);$('order-before').checked=true;$('order-after').checked=false;$('order-error').textContent='';$('order-dialog').showModal();return true;
}
function placeOrder(kind,id,targetId,position){
 if(!requireEditor()||!['before','after'].includes(position))return false;
 const record=orderRecord(kind,id),target=orderRecord(kind,targetId);if(!orderCompatible(kind,record,target))return false;
 const peers=orderPeers(kind,record),ordered=peers.filter(t=>t!==record),targetIndex=ordered.indexOf(target);if(targetIndex<0)return false;ordered.splice(targetIndex+(position==='after'?1:0),0,record);
 if(ordered.every((t,i)=>t===peers[i])){cancelOrderMove();toast('รายการอยู่ในตำแหน่งนี้แล้ว');return false}
 const peerSet=new Set(peers);let index=0;const list=(kind==='group'?state.groups:state.tasks).map(t=>peerSet.has(t)?ordered[index++]:t);if(kind==='group')state.groups=list;else state.tasks=list;arrangeTaskTree();
 orderSelection=null;orderTarget=null;if($('order-dialog').open)$('order-dialog').close();changed();toast('ย้าย '+record.name+' เป็นลำดับ '+orderLabel(kind,record).split(' · ')[0]+' แล้ว');document.querySelector('[data-reorder-kind="'+kind+'"][data-reorder-id="'+CSS.escape(id)+'"]')?.focus({preventScroll:true});return true;
}

function arrangeTaskTree(){
 const children=new Map(),roots=new Map(),ordered=[],seen=new Set();
 for(const task of state.tasks){const map=task.parentId?children:roots,key=task.parentId||task.groupId;if(!map.has(key))map.set(key,[]);map.get(key).push(task)}
 function visit(task){if(seen.has(task))return;seen.add(task);ordered.push(task);for(const child of children.get(task.id)||[])visit(child)}
 for(const group of state.groups)for(const root of roots.get(group.id)||[])visit(root);
 // Preserve any unattached records rather than dropping data while arranging the tree.
 for(const task of state.tasks)visit(task);state.tasks=ordered;
}

const DATABASE_MODEL='project-product-work-v1';


function databaseGroup(record){return state.groups.find(g=>g.id===(record.groupId||record.id))||null}
function isDatabaseGroup(group){return group?.databaseModel===DATABASE_MODEL}
function databaseProduct(record){if(!isDatabaseGroup(databaseGroup(record))||state.groups.some(g=>g.id===record.id))return null;let task=state.tasks.find(t=>t.id===record.id)||record,seen=new Set();while(task.parentId){if(seen.has(task.id))return null;seen.add(task.id);task=state.tasks.find(t=>t.id===task.parentId);if(!task)return null}return task.nodeType==='section'?task:null}
function drawingFieldsFor(record){const group=databaseGroup(record),keys=['pjCode','projectWorks','drawingGroup','product'];if(isDatabaseGroup(group)){const product=databaseProduct(record);return{pjCode:group.pjCode||'',projectWorks:group.projectWorks||'',drawingGroup:product?.drawingGroup||'',product:product?.product||''}}
 const core={},chain=[],seen=new Set();let item=record;while(item&&!seen.has(item.id)){seen.add(item.id);chain.unshift(item);item=item.parentId?state.tasks.find(t=>t.id===item.parentId):null}if(group)chain.unshift(group);for(const r of chain){for(const k of keys)if(r[k])core[k]=r[k];if(!core.pjCode&&/^PJ\d{2}-\d+$/i.test(r.name||''))core.pjCode=r.name}return core;
}




function excelExportRecords(groupId='all'){
 const all=scheduleTreeRecords(groupId);if(!state.groups.some(isDatabaseGroup))return all;
 const rows=all.filter(r=>!r.section);for(const r of rows)if(databaseIdentity(r.raw).slice(0,5).some(v=>!v))throw Error('งาน '+r.raw.name+' ยังมีข้อมูล PJ / Project Works / Group Drawing / Product / Description ไม่ครบ');return rows;
}










