  if(c==='\r'||c==='\n'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);rows.push(row);if(rows.length>40004)throw Error('CSV มีแถวมากเกิน 40,000 แถว');row=[];field='';closed=false;start=true;continue}
