function refreshCSVImport(){csvImportPreview=null;$('csv-import-confirm').disabled=true;$('csv-import-errors').textContent='';$('csv-import-preview').innerHTML='';$('csv-import-summary').textContent='เลือกไฟล์ CSV UTF-8 เพื่อดูข้อมูลก่อนนำเข้า';$('csv-new-title-field').hidden=$('csv-import-mode').value!=='append'||Boolean(csvImportSource?.database);$('csv-clear-field').hidden=$('csv-import-mode').value!=='update';if(!csvImportSource)return;
 try{const plan=buildCSVImportPlan(csvImportSource,$('csv-import-mode').value,$('csv-clear-blanks').checked,$('csv-new-title').value);csvImportPreview=plan;const count=plan.changedCount+plan.createdCount;$('csv-import-summary').textContent=csvImportSource.records.length+' รายการ · '+(plan.database?'อัปเดต '+plan.changedCount+' / เพิ่ม '+plan.createdCount+' งาน':plan.mode==='update'?'อัปเดต '+count+' รายการ':'เพิ่ม '+count+' รายการในหมวดใหม่')+' · '+plan.issues.length+' ข้อผิดพลาด';$('csv-import-errors').textContent=[...plan.issues.slice(0,12),...plan.warnings.slice(0,8)].join('\n');$('csv-import-preview').innerHTML=plan.preview.slice(0,200).map(r=>'<tr><td>'+escapeHTML(r.code)+'</td><td>'+escapeHTML(r.name)+(r.changes?.length?'<details><summary>ดูข้อมูลที่จะเปลี่ยน</summary><div class="csv-change-details">'+r.changes.map(escapeHTML).join('<br>')+'</div></details>':'')+'</td><td>'+escapeHTML(r.action)+'</td></tr>').join('');$('csv-import-confirm').disabled=!isEditor||Boolean(plan.issues.length)||!count;
 }catch(error){$('csv-import-errors').textContent=error.message}}
async function readCSVImportFile(file){if(!requireEditor())return;const token=++csvImportGeneration;csvImportSource=null;csvImportPreview=null;refreshCSVImport();if(!file)return;$('csv-import-summary').textContent='กำลังอ่าน '+file.name+'…';try{if(!/\.csv$/i.test(file.name))throw Error('กรุณาเลือกไฟล์ .csv UTF-8');if(file.size>10*1024*1024)throw Error('CSV ต้องมีขนาดไม่เกิน 10 MB');const bytes=await file.arrayBuffer();if(token!==csvImportGeneration||!isEditor)return;let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{throw Error('ไฟล์นี้ไม่ใช่ UTF-8 ให้บันทึกเป็น CSV UTF-8 ใน Excel')}
 csvImportSource=readScheduleCSV(text);$('csv-new-title').value='นำเข้า · '+file.name.replace(/\.csv$/i,'');refreshCSVImport();}catch(error){if(token!==csvImportGeneration||!isEditor)return;$('csv-import-summary').textContent='ยังไม่นำเข้าข้อมูล';$('csv-import-errors').textContent=error.message}}
function openCSVImport(){if(!requireEditor())return;csvImportGeneration++;csvImportSource=null;csvImportPreview=null;$('csv-import-file').value='';$('csv-import-mode').value='update';$('csv-clear-blanks').checked=false;$('csv-template-group').innerHTML='<option value="all">ทุกหมวดหลัก</option>'+state.groups.map(g=>'<option value="'+escapeHTML(g.id)+'">'+escapeHTML(g.name)+'</option>').join('');$('csv-template-group').value=state.groups[0]?.id||'all';refreshCSVImport();$('csv-import-dialog').showModal()}
function clearCSVImport(){csvImportGeneration++;csvImportSource=null;csvImportPreview=null}
function confirmCSVImport(){if(!requireEditor())return;const plan=csvImportPreview;if(!plan||plan.issues.length||!(plan.changedCount||plan.createdCount))return;if(plan.revision!==revision){csvImportPreview=null;$('csv-import-confirm').disabled=true;$('csv-import-errors').textContent='ตารางเปลี่ยนหลังตรวจ CSV กรุณากดตรวจข้อมูลอีกครั้ง';return}state=plan.next;changed();$('csv-import-dialog').close();toast('นำเข้า CSV แล้ว '+(plan.changedCount+plan.createdCount)+' รายการ กรุณาบันทึก HTML เพื่อเก็บลงไฟล์')}
function makeLegacyScheduleCSV(groupId='all'){const escape=(value,column)=>{let text=String(value??'');if(/^[=+\-@']/.test(text)||column===16&&/^[1-9]\d*(\.[1-9]\d*)*$/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'},lines=[[...EXCEL_HEADERS,'Node Type']];for(const r of excelExportRecords(groupId)){for(const actual of [false,true]){const t=r.view;lines.push([r.core.pjCode,r.core.projectWorks,r.core.drawingGroup,r.core.product,t.name,t.currentInfo,t.owner==='—'?'':t.owner,t.unit,t.quantity,t.workStatus,t.action,actual?t.actualStart:t.start,actual?t.actualEnd:t.end,t.approvedDate,t.remark,null,r.code,actual?'Actual':'Plan',r.depth===0?'Group':r.section?'Section':'Task'])}}return '\ufeff'+lines.map(row=>row.map(escape).join(',')).join('\r\n')+'\r\n'}
function csvDownload(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
$('import-csv').onclick=openCSVImport;
$('csv-import-file').onchange=()=>readCSVImportFile($('csv-import-file').files?.[0]);
for(const id of ['csv-import-mode','csv-clear-blanks'])$(id).onchange=refreshCSVImport;
$('csv-new-title').addEventListener('input',refreshCSVImport);
