$('csv-import-confirm').onclick=confirmCSVImport;
$('csv-template-download').onclick=()=>{try{csvDownload(makeScheduleCSV($('csv-template-group').value||'all'),'Master_Schedule_'+(state.project.reportDate||'template')+'.csv','text/csv;charset=utf-8')}catch(error){$('csv-import-errors').textContent=error.message}};
