function syncParentTrigger(){const parent=state.tasks.find(t=>t.id===$('f-parent').value),group=state.groups.find(g=>g.id===$('f-group').value),paths=taskPaths(),label=parent?(paths.get(parent.id)||'')+' · '+parent.name:group?(state.groups.indexOf(group)+1)+' '+group.name+' · ใต้หมวดหลักโดยตรง':'ใต้หัวข้องานหลักโดยตรง';$('parent-trigger-label').textContent=label;$('parent-trigger').title=label}
function closeParentPicker(restoreFocus=false){$('parent-picker').hidden=true;$('parent-trigger').setAttribute('aria-expanded','false');if(restoreFocus)$('parent-trigger').focus({preventScroll:true})}
function renderParentPicker(){if(isDatabaseGroup(state.groups.find(g=>g.id===$('f-group').value))){renderDatabaseParentPicker();return}const group=state.groups.find(g=>g.id===$('f-group').value);if(!group){$('parent-options').innerHTML='';return}const paths=taskPaths(),excluded=editingId?descendantIds(editingId):new Set();if(editingId)excluded.add(editingId);const query=$('parent-search').value.toLowerCase().trim(),selected=$('f-parent').value,rootCode=String(state.groups.indexOf(group)+1),rootMatch=!query||group.name.toLowerCase().includes(query);
 function build(task,depth,inheritedMatch){const own=inheritedMatch||[task.name,paths.get(task.id)||''].some(s=>s.toLowerCase().includes(query)),children=taskChildren(task.id).filter(t=>!excluded.has(t.id)).map(t=>build(t,depth+1,own));return{task,depth,children,match:own||children.some(n=>n.match)}}
 const roots=state.tasks.filter(t=>t.groupId===group.id&&!t.parentId&&!excluded.has(t.id)).map(t=>build(t,1,rootMatch)),visibleRoots=roots.filter(n=>n.match);let options='<button type="button" class="parent-option" role="treeitem" aria-level="1" aria-selected="'+(!selected)+'" tabindex="-1" data-parent-pick="" style="--tree-depth:0">'+treeGuides(0,[],false,visibleRoots.length>0,21)+'<span class="picker-code">'+rootCode+'</span><span class="picker-name">'+escapeHTML(group.name)+' · ใต้หมวดหลักโดยตรง</span></button>';
 function append(node,ancestors,isLast){const children=node.children.filter(n=>n.match),code=paths.get(node.task.id)||'',title=code+' · '+node.task.name;options+='<button type="button" class="parent-option" role="treeitem" aria-level="'+(node.depth+1)+'" aria-selected="'+(selected===node.task.id)+'" '+(children.length?'aria-expanded="true" ':'')+'tabindex="-1" data-parent-pick="'+escapeHTML(node.task.id)+'" title="'+escapeHTML(title)+'" style="--tree-depth:'+node.depth+'">'+treeGuides(node.depth,ancestors,isLast,children.length>0,21)+'<span class="picker-code">'+escapeHTML(code)+'</span><span class="picker-name">'+escapeHTML(node.task.name)+'</span></button>';children.forEach((child,i)=>append(child,[...ancestors,!isLast],i===children.length-1))}
 visibleRoots.forEach((node,i)=>append(node,[],i===visibleRoots.length-1));if(query&&!visibleRoots.length&&!rootMatch)options+='<div class="parent-picker-empty">ไม่พบหัวข้อที่ตรงกับคำค้น</div>';$('parent-options').innerHTML=options;
}
