const FILE_LIMIT=20000,FILE_PAGE_SIZE=100;
let localFileSession=null,localPathTimer=null,localPathController=null;
function localFileMode(){return typeof location!=='undefined'&&location.protocol==='http:'&&location.hostname==='127.0.0.1'&&location.port==='48731'}
async function localFileRequest(route,body,signal){
 if(!localFileMode())throw new Error('LOCAL_HELPER_REQUIRED');
 if(!localFileSession)localFileSession=fetch('/api/session',{cache:'no-store'}).then(async response=>{if(!response.ok)throw new Error('LOCAL_HELPER_OFFLINE');return (await response.json()).token}).catch(error=>{localFileSession=null;throw error});
 const token=await localFileSession,response=await fetch(route,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json','X-Schedule-Token':token},body:JSON.stringify(body),signal});
 const data=await response.json();if(!response.ok){if(data.error==='AUTH_REQUIRED')localFileSession=null;throw new Error(data.error||'LOCAL_REQUEST_FAILED')}return data;
}
function documentFileURL(root,path){
 if(typeof root!=='string'||typeof path!=='string'||!root.trim()||/^[\\/]|:/.test(path)||path.split(/[\\/]/).some(p=>!p||p==='.'||p==='..'))return null;
 let base=root.trim().replace(/^"|"$/g,'').replace(/\\/g,'/');
 if(/^file:/i.test(base)){try{const url=new URL(base);if(url.protocol!=='file:')return null;base=decodeURIComponent(url.pathname);if(url.hostname)base='//'+url.hostname+base;else base=base.replace(/^\/([a-z]:\/)/i,'$1')}catch{return null}}
 if(!/^[a-z]:\//i.test(base)&&!/^\/\/[^/]+\/[^/]+/.test(base))return null;
 const pieces=(base.replace(/\/+$/,'')+'/'+path.replace(/\\/g,'/')).split('/');return (base.startsWith('//')?'file:':'file:///')+pieces.map((p,i)=>/^[a-z]:$/i.test(p)?p:encodeURIComponent(p)).join('/');
}
function fileLinkMarkup(catalog,file){const href=documentFileURL(catalog?.address,file.path);return href?'<a class="document-file-link" href="'+escapeHTML(href)+'" data-file-root="'+escapeHTML(catalog.address)+'" data-file-path="'+escapeHTML(file.path)+'" target="_blank" rel="noopener" title="เปิด '+escapeHTML(file.path)+'">'+escapeHTML(file.name)+'</a>':escapeHTML(file.name)}
async function openDocumentLink(event){const link=event.target.closest('a[data-file-path]');if(!link||!localFileMode())return;event.preventDefault();if(link.dataset.opening==='true')return;link.dataset.opening='true';try{await localFileRequest('/api/open',{root:link.dataset.fileRoot,path:link.dataset.filePath})}catch(error){toast(error.message==='EXECUTABLE_NOT_ALLOWED'?'ไฟล์ชนิดนี้ไม่รองรับการเปิดจากตาราง':'เปิดไฟล์ไม่ได้ ตรวจสอบว่าไฟล์ยังอยู่และมีโปรแกรมสำหรับเปิดไฟล์นี้')}finally{link.dataset.opening='false'}}
async function readLocalFolder(){
 if(!localFileMode()||!canEditFileContext())return;const context=fileContext,path=$('file-address').value.trim();if(!path)return;
 localPathController?.abort();const controller=new AbortController();localPathController=controller;const token=++fileScanToken;setFileScanning(true);fileMessage('กำลังอ่านไฟล์จากที่อยู่ที่วาง…');
 try{const data=await localFileRequest('/api/list',{path},controller.signal);if(context!==fileContext||token!==fileScanToken||!canEditFileContext())return;if(data.truncated)data.warning='แสดงได้สูงสุด '+FILE_LIMIT+' ไฟล์ กรุณาเลือกโฟลเดอร์ย่อย';if(data.skipped)data.warning+=(data.warning?' · ':'')+'มีรายการที่อ่านไม่ได้หรือเป็นทางลัด '+data.skipped+' รายการ';acceptFileCatalog(data,null,true);$('file-address').value=data.address;}
 catch(error){if(error.name!=='AbortError'&&token===fileScanToken)fileMessage('อ่านโฟลเดอร์ไม่ได้ ตรวจสอบที่อยู่และการเข้าถึง · รายการเดิมยังอยู่')}
 finally{if(context===fileContext&&token===fileScanToken)setFileScanning(false)}
}
function scheduleLocalFolderRead(){if(!canEditFileContext())return;clearTimeout(localPathTimer);localPathController?.abort();fileScanToken++;setFileScanning(false);if(!localFileMode()){fileMessage('หากต้องการวางที่อยู่แล้วอ่านทันที ให้เปิดผ่าน Open_Master_Schedule.cmd · เปิด HTML โดยตรงยังใช้เลือกโฟลเดอร์แบบเดิมได้');return}localPathTimer=setTimeout(readLocalFolder,500)}
function applyFileDialogDraft(){if(!canEditFileContext()||!fileCatalog)return;if(fileCatalog.source!=='local'&&!localFileMode())fileCatalog.address=$('file-address').value.trim();taskFileDraft=cleanFileCatalog(fileCatalog);taskFileHandle=fileDirectoryHandle;taskFileDirty=true;$('task-file-address').value=taskFileDraft.address;renderTaskFiles()}

let fileCatalog=null,fileDirectoryHandle=null,fileScanToken=0,fileScanning=false,filePage=0,fileContext=null,fileInputContext=null,fileInputKeepSelection=false,fileFallbackKeepSelection=false;
let taskFileDraft=null,taskFileDirty=false,taskFileHandle=null;
const taskFileHandles=new Map();let fileFallbackNeeded=false;

function selectedCatalogFiles(catalog){return Array.isArray(catalog?.files)?catalog.files.filter(f=>f?.selected===true):[]}
function taskFilesBadge(task){const catalog=task.fileCatalog,count=Array.isArray(catalog?.files)?Math.min(catalog.files.length,FILE_LIMIT):0,selected=selectedCatalogFiles(catalog);return '<details class="task-files-disclosure" data-files-task="'+escapeHTML(task.id)+'" '+(expandedFileLists.has(task.id)?'open':'')+'><summary title="ยุบหรือขยายไฟล์ประกอบงาน '+escapeHTML(task.name)+'"><span class="file-disclosure-arrow" aria-hidden="true"></span><span class="file-disclosure-label">ไฟล์ที่เลือก '+selected.length.toLocaleString('th-TH')+' / '+count.toLocaleString('th-TH')+'</span></summary><div class="task-files-body">'+(selected.length?'<ul class="task-file-preview">'+selected.slice(0,5).map(f=>'<li title="'+escapeHTML(f.path)+'">'+fileLinkMarkup(catalog,f)+(fileParent(f.path)?'<small>'+escapeHTML(fileParent(f.path))+'</small>':'')+'</li>').join('')+'</ul>':'<p class="task-files-empty">ยังไม่มีไฟล์ที่เลือก</p>')+'<button type="button" class="task-selected-more" data-task-files="'+escapeHTML(task.id)+'" data-selected-only="'+(selected.length>5)+'">'+(selected.length>5?'ดูที่เลือกทั้งหมด ('+selected.length.toLocaleString('th-TH')+')':'ดูรายการไฟล์ทั้งหมด')+'</button></div></details>'}
function initTaskFiles(task){taskFileDraft=cleanFileCatalog(task.fileCatalog);taskFileDirty=false;taskFileHandle=taskFileHandles.get(task.id)||null;$('task-file-address').value=taskFileDraft?.address||'';$('task-file-address').readOnly=localFileMode();renderTaskFiles()}
function renderTaskFiles(){const count=taskFileDraft?.files.length||0,selected=selectedCatalogFiles(taskFileDraft).length;$('task-file-summary').textContent=taskFileDraft?taskFileDraft.rootName:'ยังไม่ได้เลือกโฟลเดอร์';$('task-file-count').textContent='เลือก '+selected.toLocaleString('th-TH')+' / '+count.toLocaleString('th-TH')+' ไฟล์';$('task-file-view').textContent='เลือกไฟล์ / ดูรายการ ('+count.toLocaleString('th-TH')+')';$('task-file-clear').disabled=!taskFileDraft;$('task-file-legacy').hidden=!cleanFileCatalog(state.fileCatalog)}
function commitTaskFileHandle(id){if(!taskFileDirty)return;if(taskFileHandle&&taskFileDraft)taskFileHandles.set(id,taskFileHandle);else taskFileHandles.delete(id)}
function canEditFileContext(){return isEditor&&fileContext?.kind==='draft'&&$('task-dialog').open&&fileContext.taskId===editingId}
function resetFileFilters(){filePage=0;$('file-selected-only').checked=false;$('file-search').value='';$('file-sort').value='name';$('file-recursive').checked=true;fileFilterOptions()}
function showTaskFileDialog(context,catalog,handle,address,title,path){fileScanToken++;fileContext=context;fileCatalog=cleanFileCatalog(catalog);fileDirectoryHandle=handle;$('file-address').value=address||'';$('file-dialog-title').textContent=title;$('file-dialog-path').textContent=path;resetFileFilters();setFileScanning(false);renderFileCatalog();if(fileCatalog)fileCatalogNote(true);else fileMessage(context.kind==='draft'?'ยังไม่ได้เลือกโฟลเดอร์ · ใส่ที่อยู่เพื่ออ้างอิง แล้วกดเลือกโฟลเดอร์เพื่ออนุญาตให้อ่านไฟล์':'งานนี้ยังไม่ได้ผูกโฟลเดอร์ · เลือกโฟลเดอร์ได้ในหน้าแก้ไขงาน');$('file-dialog').showModal();$('file-path-help').textContent=localFileMode()?'วางที่อยู่แล้วรอสักครู่ รายการจะขึ้นเอง · ติ๊กแล้วปิดรายการได้เลย':'เปิดผ่าน Open_Master_Schedule.cmd เพื่อวางที่อยู่แล้วอ่านทันที';if(localFileMode()&&context.kind==='draft'){if(address&&!catalog)readLocalFolder();else $('file-address').focus()}}
function openTaskDraftFiles(choose=false){if(!requireEditor()||!$('task-dialog').open)return;const path=outlinePath($('f-group').value,$('f-parent').value||null).map(n=>n.code+' '+n.name).join(' / ');showTaskFileDialog({kind:'draft',taskId:editingId},taskFileDraft,taskFileHandle,$('task-file-address').value.trim(),'ไฟล์ประกอบงาน · '+($('f-name').value.trim()||'งานใหม่'),path);if(choose){if(localFileMode())$('file-address').focus();else chooseFileDirectory()}}
function openTaskFileList(id,selectedOnly=false){const task=state.tasks.find(t=>t.id===id);if(!task)return;showTaskFileDialog({kind:'view',taskId:id},task.fileCatalog,null,task.fileCatalog?.address||'','ไฟล์ประกอบงาน · '+task.name,outlinePath(task.groupId,id).map(n=>n.code+' '+n.name).join(' / '));$('file-selected-only').checked=selectedOnly;renderFileCatalog()}
function stopFileSession(){clearTimeout(localPathTimer);localPathController?.abort();localPathController=null;fileScanToken++;fileContext=null;fileInputContext=null;fileCatalog=null;fileDirectoryHandle=null;setFileScanning(false)}

function cleanFileCatalog(raw){
 if(!raw||!Array.isArray(raw.files))return null;
 const files=raw.files.slice(0,FILE_LIMIT).filter(f=>f&&typeof f.name==='string'&&typeof f.path==='string').map(f=>({name:f.name.slice(0,1000),path:f.path.slice(0,8000),size:Number.isFinite(f.size)&&f.size>=0?f.size:0,modified:Number.isFinite(f.modified)&&f.modified>=0?f.modified:0,selected:f.selected===true}));
 return {rootName:String(raw.rootName||'โฟลเดอร์').slice(0,1000),address:String(raw.address||'').slice(0,2000),source:raw.source==='local'?'local':'picker',scannedAt:typeof raw.scannedAt==='string'?raw.scannedAt:'',warning:String(raw.warning||'').slice(0,2000),files};
}
function fileExtension(name){const i=name.lastIndexOf('.');return i>0&&i<name.length-1?name.slice(i+1).toLowerCase():'__none__'}
function fileParent(path){const i=path.lastIndexOf('/');return i<0?'':path.slice(0,i)}
function fileSizeLabel(size){if(size<1024)return size+' B';const units=['KB','MB','GB','TB'];let n=size/1024,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return n.toLocaleString('th-TH',{maximumFractionDigits:1})+' '+units[i]}
function fileDateLabel(value){return value>0&&Number.isFinite(new Date(value).getTime())?new Date(value).toLocaleString('th-TH-u-ca-gregory'): '—'}
function fileMessage(message){$('file-message').textContent=message}
function fileCatalogNote(saved=false){if(!fileCatalog)return;fileMessage((saved?'รายการของงาน: ':'อ่านรายการแล้ว: ')+fileCatalog.rootName+' · '+fileCatalog.files.length.toLocaleString('th-TH')+' ไฟล์ · '+(fileCatalog.scannedAt?new Date(fileCatalog.scannedAt).toLocaleString('th-TH-u-ca-gregory'):'ไม่ระบุเวลา')+(fileCatalog.warning?' · '+fileCatalog.warning:'')+' · รายการเป็นข้อมูล ณ เวลาที่อ่าน'+(canEditFileContext()?' · ติ๊กไฟล์แล้วปิดรายการ จากนั้นบันทึกงานเพื่อเก็บไว้':' · คลิกชื่อไฟล์เพื่อเปิด หรือเปิดหน้าแก้ไขเพื่ออ่านรายการใหม่'));}
function setFileScanning(value){fileScanning=Boolean(value);const edit=canEditFileContext();for(const id of ['file-choose','file-fallback','file-refresh','file-stop','file-remember','file-select-filtered','file-clear-filtered'])$(id).hidden=!edit||(id==='file-stop'&&!value)||(id==='file-fallback'&&!fileFallbackNeeded);$('file-choose').disabled=Boolean(value);$('file-fallback').disabled=Boolean(value);$('file-refresh').disabled=Boolean(value)||!fileCatalog;$('file-remember').hidden=true;$('file-remember').disabled=true;if(localFileMode()){$('file-choose').hidden=true;$('file-fallback').hidden=true;$('file-refresh').disabled=Boolean(value)||!$('file-address').value.trim()}$('file-address').readOnly=!edit;renderFileCatalog()}
function fileFilterOptions(){
 const extensions=new Set(),folders=new Set();
 for(const f of fileCatalog?.files||[]){extensions.add(fileExtension(f.name));let p=fileParent(f.path);while(p){folders.add(p);p=fileParent(p)}}
 $('file-extension').innerHTML='<option value="">ทุกชนิด</option>'+[...extensions].sort().map(e=>'<option value="'+escapeHTML(e)+'">'+(e==='__none__'?'ไม่มีนามสกุล':'.'+escapeHTML(e))+'</option>').join('');
 $('file-folder').innerHTML='<option value="">โฟลเดอร์หลัก</option>'+[...folders].sort((a,b)=>a.localeCompare(b,'th',{numeric:true})).map(p=>'<option value="'+escapeHTML(p)+'">'+escapeHTML(p)+'</option>').join('');
 $('file-extension').value='';$('file-folder').value='';filePage=0;
}
function filteredLocalFiles(){
 const words=$('file-search').value.trim().toLowerCase().split(/\s+/).filter(Boolean),ext=$('file-extension').value,folder=$('file-folder').value,recursive=$('file-recursive').checked;
 return (fileCatalog?.files||[]).filter(f=>{const parent=fileParent(f.path);return (!$('file-selected-only').checked||f.selected===true)&&(!ext||fileExtension(f.name)===ext)&&(recursive?(!folder||parent===folder||parent.startsWith(folder+'/')):parent===folder)&&words.every(w=>(f.name+' '+f.path).toLowerCase().includes(w))}).sort((a,b)=>($('file-sort').value==='modified'?b.modified-a.modified:$('file-sort').value==='size'?b.size-a.size:0)||a.path.localeCompare(b.path,'th',{numeric:true}));
}

function renderFileCatalog(){
 const files=filteredLocalFiles(),pages=Math.max(1,Math.ceil(files.length/FILE_PAGE_SIZE));filePage=Math.max(0,Math.min(filePage,pages-1));const page=files.slice(filePage*FILE_PAGE_SIZE,(filePage+1)*FILE_PAGE_SIZE),editable=canEditFileContext()&&!fileScanning;
 $('file-rows').innerHTML=page.map(f=>'<tr class="'+(f.selected?'file-is-selected':'')+'"><td class="file-check-cell"><input type="checkbox" data-file-selected="'+escapeHTML(f.path)+'" aria-label="แสดง '+escapeHTML(f.path)+' บนตารางหลัก" '+(f.selected?'checked ':'')+(!editable?'disabled ':'')+'></td><td>'+fileLinkMarkup(fileCatalog,f)+'</td><td>'+escapeHTML(fileParent(f.path)||'—')+'</td><td>'+escapeHTML(fileExtension(f.name)==='__none__'?'—':'.'+fileExtension(f.name))+'</td><td>'+fileSizeLabel(f.size)+'</td><td>'+escapeHTML(fileDateLabel(f.modified))+'</td></tr>').join('')||'<tr><td colspan="6" class="file-empty">'+(fileCatalog?'ไม่พบไฟล์ที่ตรงกับตัวกรอง':'เลือกโฟลเดอร์เพื่อแสดงรายการ')+'</td></tr>';
 $('file-count').textContent='แสดง '+files.length.toLocaleString('th-TH')+' / '+(fileCatalog?.files.length||0).toLocaleString('th-TH')+' ไฟล์';$('file-page').textContent='หน้า '+(filePage+1)+' / '+pages;$('file-prev').disabled=filePage===0;$('file-next').disabled=filePage>=pages-1;
 const selected=page.filter(f=>f.selected).length;$('file-select-page').checked=page.length>0&&selected===page.length;$('file-select-page').indeterminate=selected>0&&selected<page.length;$('file-select-page').disabled=!editable||!page.length;
 $('file-selection-count').textContent='เลือกขึ้นตารางหลัก '+selectedCatalogFiles(fileCatalog).length.toLocaleString('th-TH')+' ไฟล์';$('file-select-filtered').disabled=!editable||!files.length;$('file-clear-filtered').disabled=!editable||!files.some(f=>f.selected);
}
function setCatalogFileSelected(path,selected){if(!canEditFileContext()||fileScanning||typeof selected!=='boolean')return false;const file=fileCatalog?.files.find(f=>f.path===path);if(!file)return false;file.selected=selected;renderFileCatalog();const replacement=[...$('file-rows').querySelectorAll('[data-file-selected]')].find(el=>el.dataset.fileSelected===path);replacement?.focus({preventScroll:true});return true}
function selectCatalogScope(selected,scope='page'){if(!canEditFileContext()||fileScanning||typeof selected!=='boolean')return false;const filtered=filteredLocalFiles(),files=scope==='filtered'?filtered:filtered.slice(filePage*FILE_PAGE_SIZE,(filePage+1)*FILE_PAGE_SIZE);for(const file of files)file.selected=selected;renderFileCatalog();return true}

function loadSavedFileCatalog(){if($('file-dialog').open)$('file-dialog').close();stopFileSession();taskFileDraft=null;taskFileDirty=false;taskFileHandle=null;taskFileHandles.clear();}

function acceptFileCatalog(catalog,handle,keepSelection=false){
 const next=cleanFileCatalog(catalog),sameFolder=fileCatalog&&next&&fileCatalog.rootName===next.rootName&&((handle&&handle===fileDirectoryHandle)||fileCatalog.address===next.address);
 if(keepSelection&&sameFolder){const paths=new Set(selectedCatalogFiles(fileCatalog).map(f=>f.path));for(const file of next.files)file.selected=paths.has(file.path);const missing=paths.size-selectedCatalogFiles(next).length;if(missing>0)next.warning+=(next.warning?' · ':'')+'ไฟล์ที่เคยเลือกไม่พบ '+missing+' ไฟล์';}
 fileCatalog=next;fileDirectoryHandle=handle;$('file-search').value='';$('file-selected-only').checked=false;fileFilterOptions();renderFileCatalog();fileCatalogNote();
}

async function scanFileDirectory(handle,keepSelection=false){
 if(!canEditFileContext())return;const token=++fileScanToken,address=$('file-address').value.trim(),files=[],warnings=[];let reachedLimit=false,visited=0;setFileScanning(true);fileMessage('กำลังอ่านโฟลเดอร์ '+handle.name+'…');
 async function walk(directory,prefix){
  try{for await(const entry of directory.values()){
   if(token!==fileScanToken||!canEditFileContext()||reachedLimit)return;
   if(++visited%200===0){fileMessage('กำลังอ่าน '+handle.name+' · พบ '+files.length+' ไฟล์…');await new Promise(resolve=>setTimeout(resolve,0));if(token!==fileScanToken)return;}
   const path=prefix+entry.name;
   if(entry.kind==='directory')await walk(entry,path+'/');
   else if(entry.kind==='file'){
    if(files.length>=FILE_LIMIT){reachedLimit=true;return}
    try{const f=await entry.getFile();if(token!==fileScanToken)return;files.push({name:entry.name,path,size:f.size,modified:f.lastModified})}catch(e){if(warnings.length<5)warnings.push('อ่านไม่ได้: '+path)}
   }
  }}catch(e){if(prefix==='')throw e;if(warnings.length<5)warnings.push('อ่านโฟลเดอร์ไม่ได้: '+prefix)}
 }
 try{await walk(handle,'');if(token!==fileScanToken||!canEditFileContext())return;if(reachedLimit)warnings.push('แสดงได้สูงสุด '+FILE_LIMIT.toLocaleString('th-TH')+' ไฟล์ กรุณาเลือกโฟลเดอร์ที่เล็กลงเพื่ออ่านให้ครบ');acceptFileCatalog({rootName:handle.name,address,scannedAt:new Date().toISOString(),warning:warnings.join(' · '),files},handle,keepSelection)}
 catch(e){if(token===fileScanToken)fileMessage('อ่านโฟลเดอร์ไม่สำเร็จ กรุณาเลือกโฟลเดอร์อีกครั้ง · รายการเดิมยังอยู่')}
 finally{if(token===fileScanToken)setFileScanning(false)}
}
async function chooseFileDirectory(keepSelection=false){
 if(fileScanning||!canEditFileContext())return;const context=fileContext;
 if(!window.showDirectoryPicker){openFallbackDirectoryInput(keepSelection);return}
 try{const handle=await window.showDirectoryPicker({mode:'read'});if(context!==fileContext||!canEditFileContext())return;await scanFileDirectory(handle,keepSelection)}catch(e){if(context===fileContext&&canEditFileContext()&&e.name!=='AbortError'){fileFallbackNeeded=true;fileFallbackKeepSelection=keepSelection;setFileScanning(false);fileMessage('เปิดตัวเลือกโฟลเดอร์หลักไม่ได้ กด “เลือกโฟลเดอร์แบบสำรอง” เพื่ออ่านรายการ')}}
}
function importDirectoryFiles(list,keepSelection=false){
 if(fileScanning||!canEditFileContext()||!list?.length)return;
 const first=list[0].webkitRelativePath||list[0].name,rootName=first.includes('/')?first.split('/')[0]:'โฟลเดอร์ที่เลือก',files=Array.from(list).slice(0,FILE_LIMIT).map(f=>{const p=f.webkitRelativePath||f.name;return {name:f.name,path:p.includes('/')?p.slice(p.indexOf('/')+1):p,size:f.size,modified:f.lastModified}});
 acceptFileCatalog({rootName,address:$('file-address').value.trim(),scannedAt:new Date().toISOString(),warning:list.length>FILE_LIMIT?'แสดงได้สูงสุด '+FILE_LIMIT+' ไฟล์ กรุณาเลือกโฟลเดอร์ที่เล็กลงเพื่ออ่านให้ครบ':'',files},null,keepSelection);setFileScanning(false);
}
function rememberFileCatalog(){if(!requireEditor()||!canEditFileContext())return;$('file-dialog').close()}
$('file-choose').onclick=()=>chooseFileDirectory(false);
function openFallbackDirectoryInput(keepSelection=false){if(!canEditFileContext()||fileScanning)return;fileInputContext=fileContext;fileInputKeepSelection=keepSelection;$('file-directory-input').value='';$('file-directory-input').click()}
$('file-fallback').onclick=()=>openFallbackDirectoryInput(fileFallbackKeepSelection);
$('file-directory-input').onchange=e=>{if(fileInputContext===fileContext&&fileContext)importDirectoryFiles(e.target.files,fileInputKeepSelection);fileInputContext=null;e.target.value=''};
$('file-refresh').onclick=async()=>{if(fileScanning||!canEditFileContext())return;if(localFileMode()){await readLocalFolder();return}if(fileDirectoryHandle)await scanFileDirectory(fileDirectoryHandle,true);else await chooseFileDirectory(true)};
$('file-stop').onclick=()=>{if(!fileScanning)return;clearTimeout(localPathTimer);localPathController?.abort();fileScanToken++;setFileScanning(false);fileMessage('หยุดอ่านแล้ว · รายการเดิมยังอยู่')};
$('file-remember').onclick=rememberFileCatalog;
$('file-address').addEventListener('input',scheduleLocalFolderRead);
$('file-address').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(localPathTimer);readLocalFolder()}});
document.addEventListener('click',openDocumentLink);
$('file-rows').onchange=e=>{const input=e.target.closest('[data-file-selected]');if(input)setCatalogFileSelected(input.dataset.fileSelected,input.checked)};
$('file-select-page').onchange=e=>selectCatalogScope(e.target.checked,'page');
$('file-select-filtered').onclick=()=>selectCatalogScope(true,'filtered');
$('file-clear-filtered').onclick=()=>selectCatalogScope(false,'filtered');
for(const id of ['file-search','file-extension','file-folder','file-recursive','file-sort','file-selected-only'])$(id).addEventListener(id==='file-search'?'input':'change',()=>{filePage=0;renderFileCatalog()});
$('file-prev').onclick=()=>{filePage--;renderFileCatalog()};$('file-next').onclick=()=>{filePage++;renderFileCatalog()};

$('task-file-choose').onclick=()=>openTaskDraftFiles(true);
$('task-file-view').onclick=()=>openTaskDraftFiles();
$('task-file-clear').onclick=()=>{if(!requireEditor()||!$('task-dialog').open)return;taskFileDraft=null;taskFileHandle=null;taskFileDirty=true;$('task-file-address').value='';renderTaskFiles()};
$('task-file-legacy').onclick=()=>{if(!requireEditor()||!$('task-dialog').open)return;const catalog=cleanFileCatalog(state.fileCatalog);if(!catalog)return;taskFileDraft=catalog;taskFileHandle=null;taskFileDirty=true;$('task-file-address').value=catalog.address;renderTaskFiles()};
$('task-file-address').addEventListener('input',()=>{if(isEditor&&taskFileDraft)taskFileDirty=true});
$('file-dialog').addEventListener('close',()=>{applyFileDialogDraft();stopFileSession()});
$('task-dialog').addEventListener('close',()=>{if($('file-dialog').open)$('file-dialog').close();stopFileSession();taskFileDraft=null;taskFileHandle=null;taskFileDirty=false});
loadSavedFileCatalog();
